import axios from 'axios';
import { isTokenExpired } from '@/utils/jwt';
import store from '@/store';

const API_URL = process.env.VUE_APP_API_URL || '';

console.log('API URL:', API_URL);

// Create axios instance with timeout
const axiosInstance = axios.create({
  baseURL: API_URL,
  timeout: 30000, // 30 seconds timeout
  headers: {
    'Content-Type': 'application/json'
  }
});

// Add request interceptor
axiosInstance.interceptors.request.use(
  async (config) => {
    console.log('Request interceptor:', {
      url: config.url,
      method: config.method,
      headers: config.headers
    });

    const accessToken = store.getters['auth/accessToken'];
    
    if (accessToken) {
      // Check if token is expired
      if (isTokenExpired(accessToken)) {
        console.log('Token expired, attempting refresh');
        try {
          // Try to refresh the token
          await store.dispatch('auth/refreshToken');
        } catch (error) {
          console.error('Token refresh failed:', error);
          // If refresh fails, redirect to login
          store.dispatch('auth/logout');
          window.location.href = '/';
          return Promise.reject(error);
        }
      }
      
      // Add token to request headers
      config.headers.Authorization = `Bearer ${store.getters['auth/accessToken']}`;
    }
    
    return config;
  },
  (error) => {
    console.error('Request interceptor error:', error);
    return Promise.reject(error);
  }
);

// Add response interceptor
axiosInstance.interceptors.response.use(
  (response) => {
    console.log('Response interceptor success:', {
      url: response.config.url,
      status: response.status,
      data: response.data
    });
    return response;
  },
  async (error) => {
    console.error('Response interceptor error:', {
      url: error.config?.url,
      status: error.response?.status,
      message: error.message,
      data: error.response?.data
    });

    const originalRequest = error.config;
    
    // If error is 401 and we haven't tried to refresh token yet
    if (error.response?.status === 401 && !originalRequest._retry) {
      console.log('401 error, attempting token refresh');
      originalRequest._retry = true;
      
      try {
        // Try to refresh the token
        await store.dispatch('auth/refreshToken');
        
        // Retry the original request with new token
        originalRequest.headers.Authorization = `Bearer ${store.getters['auth/accessToken']}`;
        return axiosInstance(originalRequest);
      } catch (refreshError) {
        console.error('Token refresh failed:', refreshError);
        // If refresh fails, logout and redirect to login
        store.dispatch('auth/logout');
        window.location.href = '/';
        return Promise.reject(refreshError);
      }
    }
    
    return Promise.reject(error);
  }
);

class AuthService {
  async login(credentials) {
    console.log('AuthService.login called:', { credentials });
    try {
      const response = await axiosInstance.post('/users/tokens/', credentials);
      console.log('Login response:', response.data);
      return {
        access: response.data.access,
        refresh: response.data.refresh,
        user: response.data.user
      };
    } catch (error) {
      console.error('Login error in service:', error);
      throw this.handleError(error);
    }
  }

  async requestPasswordReset(email) {
    try {
      const response = await axiosInstance.post('/auth/forgot-password', { email });
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  async confirmPasswordReset(data) {
    try {
      const response = await axiosInstance.post('/users/password/reset/confirm/', data);
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  async refreshToken(refreshToken) {
    try {
      const response = await axiosInstance.post('/users/token/refresh/', {
        refresh: refreshToken
      });
      return {
        access: response.data.access,
        refresh: response.data.refresh
      };
    } catch (error) {
      throw this.handleError(error);
    }
  }

  handleError(error) {
    console.log('Handling error:', {
      code: error.code,
      message: error.message,
      response: error.response,
      request: error.request
    });

    if (error.code === 'ECONNABORTED') {
      return {
        message: 'Превышено время ожидания ответа от сервера',
        status: 0
      };
    }
    
    if (error.response) {
      // The request was made and the server responded with a status code
      // that falls out of the range of 2xx
      const message = error.response.data?.message || 
                     error.response.data?.detail || 
                     'Произошла ошибка при выполнении запроса';
      return {
        message,
        status: error.response.status
      };
    } else if (error.request) {
      // The request was made but no response was received
      return {
        message: 'Сервер не отвечает. Пожалуйста, попробуйте позже',
        status: 0
      };
    } else {
      // Something happened in setting up the request that triggered an Error
      return {
        message: error.message || 'Произошла ошибка при отправке запроса',
        status: -1
      };
    }
  }
}

export default new AuthService(); 