<script>
import DashboardHeader from '@/components/layout/DashboardHeader.vue';
import { mapActions } from 'vuex';

export default {
  name: 'DashboardPage',
  components: { DashboardHeader },
  data() {
    return {
      searchQuery: ''
    };
  },
  methods: {
    ...mapActions('auth', { logoutAction: 'logout' }),
    logout() {
      this.logoutAction().then(() => {
